deps = {
    "app-transfer": ["svc-account", "svc-fep"],
    "svc-account": ["db-core"],
    "svc-fep": ["net-ext-line"],
    "app-card": ["svc-account"],
}
alerts = {"app-transfer", "svc-account", "app-card", "db-core"}

def below(n, seen=None):
    seen = seen or set()
    for c in deps.get(n, []):
        if c not in seen:
            seen.add(c); below(c, seen)
    return seen

roots = [a for a in alerts if not (below(a) & alerts)]
def path(a, goal):
    if a == goal: return [a]
    for c in deps.get(a, []):
        p = path(c, goal)
        if p: return [a] + p
for r in roots:
    print("원인 후보:", r)
    for a in sorted(alerts - {r}):
        print("  전파 경로:", " → ".join(path(a, r)))
print(f"알림 {len(alerts)}개 → 사건 {len(roots)}건으로 묶음")

# 원인 후보: db-core
#   전파 경로: app-card → svc-account → db-core
#   전파 경로: app-transfer → svc-account → db-core
#   전파 경로: svc-account → db-core
